"use client";

import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox";
import { Icon } from "@iconify/react";

import { cn } from "@/lib/utils";
import { controlChecked, focusRing } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** Mallow Checkbox: an ink outline when empty, and the solid violet primary finish with a white check when ticked. */
function Checkbox({ className, indeterminate, ...props }: WithClassName<CheckboxPrimitive.Root.Props>) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      indeterminate={indeterminate}
      className={cn(
        "peer relative grid size-5 shrink-0 place-items-center rounded-(--radius-sm) border-2 border-foreground/50",
        "transition-[background-color,border-color,box-shadow] duration-fast ease-(--ease-out)",
        "hover:border-foreground/70",
        controlChecked,
        "data-[checked]:border-transparent data-[indeterminate]:border-transparent",
        "data-[indeterminate]:bg-(image:--violet-face) data-[indeterminate]:text-primary-foreground data-[indeterminate]:shadow-(--violet-edge)",
        focusRing,
        "data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50",
        className,
      )}
      {...props}
    >
      <CheckboxPrimitive.Indicator data-slot="checkbox-indicator" className="size-full grid place-items-center">
        {indeterminate ? (
          <Icon icon="iconoir:minus" className="size-3.5" aria-hidden="true" />
        ) : (
          <Icon icon="iconoir:check" className="size-3.5" aria-hidden="true" />
        )}
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  );
}
Checkbox.displayName = "Checkbox";

export { Checkbox };
